// Body mesh + baked SDF for the T-shirt scene (generated by `npm run assets`).
// ?sdf=bake skips the SDF download and bakes it in wasm instead.
// A DXF-AAMA garment (S3): toml + DXF + an SDF over its own box (also from `npm run assets`).
export async function loadGarmentAssets(name) {
  const t0 = performance.now();
  const get = async (path) => {
    const r = await fetch(path);
    if (!r.ok) throw new Error(`missing ${path}: run \`npm run assets\``);
    return r;
  };
  const obj = await (await get('/assets/makehuman_body_m.obj')).text();
  const toml = await (await get(`/assets/garments/${name}/garment.toml`)).text();
  const dxf = await (await get(`/assets/garments/${name}/garment.dxf`)).text();
  const sdf = new Uint8Array(await (await get(`/assets/garments/${name}/sdf.bin`)).arrayBuffer());
  return { garment: name, obj, toml, dxf, sdf, fetch_ms: performance.now() - t0, sdf_download_bytes: sdf.length };
}

export async function loadTshirtAssets(q) {
  const t0 = performance.now();
  const obj = await (await fetch('/assets/makehuman_body_m.obj')).text();
  let sdf = new Uint8Array();
  if (q.get('sdf') !== 'bake') {
    const r = await fetch('/assets/sdf_4mm.bin');
    if (!r.ok) throw new Error('missing /assets/sdf_4mm.bin: run `npm run assets` (or use ?sdf=bake)');
    sdf = new Uint8Array(await r.arrayBuffer());
  }
  return { obj, sdf, fetch_ms: performance.now() - t0, sdf_download_bytes: sdf.length };
}
